rgb: 74, 222, 128;\n  --zn-warn:    #fbbf24; --zn-warn-rgb:    251, 191, 36;\n  --zn-danger:  #f87171; --zn-danger-rgb:  248, 113, 113;\n  --zn-info:    #a78bfa;\n\n  /* 兼容旧别名（旧代码用 --zn-primary 等名） */\n  --zn-primary: var(--zn-accent);\n  --zn-primary-dim: var(--zn-accent-dim);\n  --zn-text: var(--zn-text-primary);\n  --zn-text-dim: var(--zn-text-muted);\n  --zn-border: var(--zn-border-light);\n}\n\n/* ════════════════════════════════════════\n   浅色 · 白昼樱花\n   ════════════════════════════════════════ */\n.zhino-root[data-theme='light'] {\n  --zn-bg: #fdf6fb;                          /* 暖樱白 */\n  --zn-glass-bg: rgba(253, 246, 251, 0.96);  /* 近实色樱花白 */\n  --zn-glass-border: rgba(167, 139, 250, 0.28);\n  --zn-glass-highlight: inset 0 1px 0 rgba(255, 255, 255, 0.6);\n\n  --zn-accent: #7c3aed;                      /* 加深保对比 */\n  --zn-accent-rgb: 124, 58, 237;\n  --zn-accent-dim: rgba(139, 92, 246, 0.10);\n  --zn-accent-glow: rgba(139, 92, 246, 0.25);\n\n  --zn-text-primary: #2a2440;\n  --zn-text-regular: #5a527a;\n  --zn-text-muted:   #6f6888;\n\n  --zn-bg-surface1: rgba(139, 92, 246, 0.04);\n  --zn-bg-surface2: rgba(139, 92, 246, 0.08);\n  --zn-surface-sunken: rgba(139, 92, 246, 0.05);\n  --zn-card-bg: #ffffff;\n\n  --zn-border-light: rgba(42, 36, 64, 0.08);\n  --zn-border-base:  rgba(42, 36, 64, 0.16);\n\n  --zn-star: rgba(139, 92, 246, 0.45);\n  --zn-star-dim: rgba(255, 182, 213, 0.6);\n\n  --zn-shadow-glass: 0 24px 48px rgba(180, 160, 200, 0.28);\n  --zn-shadow-soft: 0 4px 16px rgba(180, 160, 200, 0.18);\n  --zn-glow-accent: 0 0 24px var(--zn-accent-glow);\n\n  --zn-success: #16a34a; --zn-success-rgb: 22, 163, 74;\n  --zn-warn:    #d97706; --zn-warn-rgb:    217, 119, 6;\n  --zn-danger:  #dc2626; --zn-danger-rgb:  220, 38, 38;\n  --zn-info:    #8b5cf6;\n}\n"],"sourceRoot":""}]);
