export const MIN_VALID_CONTENT_TEXT_LENGTH = 200;
export function countContentTextLength(text) {
    return (text || '').replace(/\s+/g, '').length;
}
export function isValidMainContent(text) {
    return countContentTextLength(text) >= MIN_VALID_CONTENT_TEXT_LENGTH;
}
export const DEFAULT_MESSAGE_PARSER_TAGS = {
    angleChainTags: [
        // 星光预设四段流水线
        'thinking_left',
        'thinking_right',
        'thinking_love',
        'thinking_director',
        // 常见通用形态
        'thinking',
        'think',
        'noodbox',
    ],
    bracketChainTags: ['thinking', 'reasoning'],
    commentChainPairs: [
        ['<!-- begin_of_Subtext_think -->', '<!-- end_of_Subtext_think -->'],
    ],
    structureTags: [
        'UpdateVariable',
        'choice',
        'elapsed',
        'safe',
        'theater',
        'recap',
        'parallel_world',
        'branches',
        'meow_FM',
        'plot_outline',
    ],
    contentTags: ['content'],
    timeTags: ['time'],
};
/** 思维链开头的裸特征（无标签、用于识别被截断的思维链） */
const CHAIN_HEAD_LITERALS = ['[metacognition]'];
let activeTags = DEFAULT_MESSAGE_PARSER_TAGS;
// 以下均由 rebuildTagTables() 根据 activeTags 重建
let CHAIN_PAIRS = [];
let CHAIN_LONE_CLOSERS = [];
let CHAIN_HEADS = [];
let CHAIN_RESIDUE_RE = /$^/;
let STRUCTURE_BLOCK_RE = /$^/;
let STRUCTURE_BARE_RE = /$^/;
/** 正文块：`<content>…</content>`（标签名可配置） */
let CONTENT_BLOCK_RE = /$^/;
/** 时间块：`<time>…</time>`（标签名可配置） */
let TIME_BLOCK_RE = /$^/;
const HTML_COMMENT_RE = /<!--[\s\S]*?-->/g;
/** 正则元字符转义（用于把标签名拼进正则） */
function escapeRe(text) {
    return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
function rebuildTagTables() {
    const tags = activeTags;
    CHAIN_PAIRS = [
        ...tags.commentChainPairs.map(p => [p[0], p[1]]),
        ...tags.angleChainTags.map(n => [`<${n}>`, `</${n}>`]),
        ...tags.bracketChainTags.map(n => [`[${n}]`, `[/${n}]`]),
    ];
    CHAIN_LONE_CLOSERS = [
        ...tags.angleChainTags.map(n => `</${n}>`),
        ...tags.bracketChainTags.map(n => `[/${n}]`),
        ...tags.commentChainPairs.map(p => p[1]),
    ];
    CHAIN_HEADS = [
        ...CHAIN_HEAD_LITERALS,
        ...tags.commentChainPairs.map(p => p[0]),
        // 开启标签被 prefill 吃掉后剩下的裸形态（`thinking_left>`）也要认
        ...tags.angleChainTags.flatMap(n => [`${n}>`, `<${n}>`]),
        ...tags.bracketChainTags.map(n => `[${n}]`),
    ];
    const angleAlt = tags.angleChainTags.map(escapeRe).join('|');
    const bracketAlt = tags.bracketChainTags.map(escapeRe).join('|');
    const commentAlt = tags.commentChainPairs
        .map(p => `${escapeRe(p[0])}|${escapeRe(p[1])}`)
        .join('|');
    CHAIN_RESIDUE_RE = new RegExp((angleAlt ? `<\\/?(?:${angleAlt})>|` : '')
        + (bracketAlt ? `\\[\\/?(?:${bracketAlt})\\]|` : '')
        + (commentAlt ? `(?:${commentAlt})|` : '')
        + (angleAlt ? `^(?:${angleAlt})>\\s*` : '^$^'), 'gim');
    const structAlt = tags.structureTags.map(escapeRe).join('|');
    STRUCTURE_BLOCK_RE = structAlt
        ? new RegExp(`<(${structAlt})\\b[^>]*>[\\s\\S]*?<\\/\\1>`, 'gi')
        : /$^/;
    STRUCTURE_BARE_RE = structAlt
        ? new RegExp(`<\\/?(?:${structAlt})\\b[^>]*>`, 'gi')
        : /$^/;
    // ⚠️ 这里**不能用 `\b`**：玩家可能填中文标签（如「正文」），而 JS 的 `\b` 只认 ASCII 词字符，
    //    `<正文>` 会被判成"无边界"而匹配失败。改用「后跟空白 / `/` / `>`」的显式断言。
    const contentAlt = tags.contentTags.map(escapeRe).join('|');
    CONTENT_BLOCK_RE = contentAlt
        ? new RegExp(`<(${contentAlt})(?=[\\s/>])[^>]*>([\\s\\S]*?)<\\/\\1>`, 'gi')
        : /$^/;
    const timeAlt = tags.timeTags.map(escapeRe).join('|');
    TIME_BLOCK_RE = timeAlt
        ? new RegExp(`<(${timeAlt})(?=[\\s/>])[^>]*>[\\s\\S]*?<\\/\\1>`, 'gi')
        : /$^/;
}
/**
 * 找到「最早的正文标签开标签」下标（多个正文标签任一命中即算，取最靠前的那个）。
 * 注意：与旧实现一致，用 `<name` 前缀匹配（宽松），以兼容 `<content style=...>` 这类带属性写法。
 */
function contentOpenIndexOf(text, from = 0) {
    let best = -1;
    for (const tag of activeTags.contentTags) {
        const i = indexOfCI(text, `<${tag}`, from);
        if (i >= 0 && (best < 0 || i < best))
            best = i;
    }
    return best;
}
/** 取出最早出现的时间块内容（标签名可配置） */
function firstTimeBlockText(text) {
    for (const m of text.matchAll(TIME_BLOCK_RE)) {
        return m[0].replace(/^<[^>]*>/, '').replace(/<\/[^>]*>$/, '').trim();
    }
    return null;
}
rebuildTagTables();
/**
 * 覆盖标签配置（换预设时调用，不必改代码）。
 * 例如接入新预设的思维链标签：
 *   configureMessageParser({ angleChainTags: ['analysis', 'draft', 'thinking'] });
 */
export function configureMessageParser(patch) {
    activeTags = { ...activeTags, ...patch };
    rebuildTagTables();
}
/** 读取当前生效的标签配置 */
export function getMessageParserTags() {
    return activeTags;
}
/**
 * 清洗用户填写的标签：去掉可能顺手写上的尖括号／方括号／斜杠与空白，去重。
 * 用户填 `<content>`、`[thinking]`、`content` 都会被归一成 `content`。
 */
function sanitizeTagNames(list) {
    const out = [];
    const seen = new Set();
    for (const raw of list || []) {
        const name = String(raw || '')
            .trim()
            .replace(/^[<[/\s]+/, '')
            .replace(/[>\]]+$/, '')
            .trim();
        if (!name)
            continue;
        const key = name.toLowerCase();
        if (seen.has(key))
            continue;
        seen.add(key);
        out.push(name);
    }
    return out;
}
/**
 * 应用「预设适配」弹窗里玩家填的标签。
 *
 * 语义：**追加**（内置默认 + 玩家自定义），**同类任一命中即读取** ——
 * 所以留空 = 完全走内置默认（兼容星光预设与 [metacognition] 那套），
 * 填了也不会把默认标签弄丢，只是多认几套写法。
 *
 * 每次调用都从 DEFAULT 重建，重复调用不会累积。
 */
export function applyCustomOutputTags(custom) {
    const thinking = sanitizeTagNames(custom?.thinking);
    const content = sanitizeTagNames(custom?.content);
    const time = sanitizeTagNames(custom?.time);
    activeTags = {
        ...DEFAULT_MESSAGE_PARSER_TAGS,
        angleChainTags: [...DEFAULT_MESSAGE_PARSER_TAGS.angleChainTags, ...thinking],
        bracketChainTags: [...DEFAULT_MESSAGE_PARSER_TAGS.bracketChainTags, ...thinking],
        contentTags: [...DEFAULT_MESSAGE_PARSER_TAGS.contentTags, ...content],
        timeTags: [...DEFAULT_MESSAGE_PARSER_TAGS.timeTags, ...time],
    };
    rebuildTagTables();
}
/**
 * 剥掉「正文之外的结构性块」（变量更新／剧情选项／时间结算／防截断尾巴等）。
 * 仅在无 <content> 标签、整条消息走兜底时使用——实测这类泄漏在真实数据里有上百条。
 * 注意：不剥离 <inner>（星光预设的"心里话"，按约定保留在正文里）。
 */
export function stripStructureBlocks(text) {
    if (!text)
        return text;
    let out = text.replace(STRUCTURE_BLOCK_RE, '');
    out = out.replace(STRUCTURE_BARE_RE, '');
    return out;
}
/** 大小写不敏感查找 */
function indexOfCI(haystack, needle, from = 0) {
    return haystack.toLowerCase().indexOf(needle.toLowerCase(), from);
}
/** 去掉思维链残留标记后是否只剩空白 */
function isBlankAfterResidue(text) {
    return text
        .replace(CHAIN_RESIDUE_RE, '')
        .replace(TIME_BLOCK_RE, '')
        .replace(HTML_COMMENT_RE, '')
        .replace(/\s+/g, '') === '';
}
/**
 * 把一条 AI 消息拆成「纯正文」+「思维链」。
 */
export function parseAssistantMessage(messageText) {
    const raw = messageText || '';
    if (!raw)
        return { content: '', thinkingChain: '' };
    let body = raw;
    const chainParts = [];
    // 1) 成对思维链块
    for (const [open, close] of CHAIN_PAIRS) {
        let from = 0;
        for (;;) {
            const o = indexOfCI(body, open, from);
            if (o < 0)
                break;
            const c = indexOfCI(body, close, o + open.length);
            if (c < 0)
                break;
            chainParts.push(body.slice(o + open.length, c));
            body = body.slice(0, o) + body.slice(c + close.length);
            from = o;
        }
    }
    // 2) 残缺形态：只有闭合标记，标记之前的内容就是思维链
    //    仅在闭合标记出现在正文标签之前时才认（避免误吞正文）
    const contentOpenIdx0 = contentOpenIndexOf(body);
    let loneIdx = -1;
    let loneTok = '';
    for (const tok of CHAIN_LONE_CLOSERS) {
        const i = indexOfCI(body, tok);
        if (i < 0)
            continue;
        if (contentOpenIdx0 >= 0 && i > contentOpenIdx0)
            continue;
        if (loneIdx < 0 || i < loneIdx) {
            loneIdx = i;
            loneTok = tok;
        }
    }
    if (loneIdx >= 0) {
        chainParts.push(body.slice(0, loneIdx));
        body = body.slice(loneIdx + loneTok.length);
    }
    // 2.5) 截断的思维链：整条消息从思维链开头起、既无闭合标记也无正文标签
    //      （生成被中断，正文压根没写出来）→ 全部归思维链，正文判空
    if (contentOpenIdx0 < 0 && loneIdx < 0) {
        const head = body.replace(/^\s+/, '').toLowerCase();
        const matchedHead = CHAIN_HEADS.find(h => head.startsWith(h.toLowerCase()));
        if (matchedHead) {
            chainParts.push(body);
            body = '';
        }
    }
    // 3) 取正文
    const contentOpenIdx = contentOpenIndexOf(body);
    let content;
    if (contentOpenIdx >= 0) {
        const matches = Array.from(body.matchAll(CONTENT_BLOCK_RE))
            .map(m => ({ idx: m.index ?? 0, text: (m[2] || '').trim() }))
            .filter(x => x.text)
            .sort((a, b) => a.idx - b.idx);
        content = matches.map(m => m.text).join('\n\n');
        // 正文标签之前的残留（时间块除外）= 思维链尾巴，兜底收走
        const pre = body.slice(0, contentOpenIdx);
        if (!isBlankAfterResidue(pre))
            chainParts.push(pre);
    }
    else {
        // 无正文标签：整条消息兜底当正文，但先剥掉正文之外的结构性块
        // （变量更新／剧情选项／时间结算／防截断尾巴），否则会被当成叙事喂给分析
        content = stripStructureBlocks(body);
    }
    // 4) 清洗正文：元注释（草稿/杀比拟检查之类）与残留标记不进正文
    content = content
        .replace(HTML_COMMENT_RE, '')
        .replace(CHAIN_RESIDUE_RE, '')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
    // 5) 前置时间信息（时间标签名可配置）
    const timeText = firstTimeBlockText(raw);
    if (timeText) {
        content = `[时间 ${timeText}]\n${content}`;
    }
    // 6) 归一化思维链
    const thinkingChain = chainParts
        .join('\n')
        .replace(TIME_BLOCK_RE, '')
        .replace(CHAIN_RESIDUE_RE, '')
        .replace(/[ \t]+\n/g, '\n')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
    return { content, thinkingChain };
}
/**
 * 从AI消息中提取正文内容，并前置 <time> 标签信息
 * （思维链会被剥离；需要思维链请用 parseAssistantMessage）
 */
export function extractContentFromMessage(messageText) {
    return parseAssistantMessage(messageText).content;
}
/**
 * 把思维链格式化成可投递给分析的文本块。
 * 标签里明确写清「仅供识别、勿当剧情」，压住模型把构思草稿当事实的倾向。
 */
export function formatThinkingChainForAnalysis(thinkingChain) {
    const text = (thinkingChain || '').trim();
    if (!text)
        return '';
    return [
        '【思维链·角色与视角锚点（仅供识别说话人与在场角色，其中"草稿/构思/模拟段落"尚未发生，严禁当作剧情事实）】',
        text,
    ].join('\n');
}
